import {renderMarkdown} from './ui/markdown.js';
export async function mountResearch(product=''){
 const parent=document.querySelector('#workspaceBody');if(!parent)return;
 const host=document.createElement('section');host.className='research-agent';host.innerHTML=`<span class="eyebrow">小木 / RESEARCH AGENT</span><h2>品种深度研究 Agent</h2><p>输入一个品种，按中证1000专题的研究框架，生成有来源、有反证、有下一步检查点的报告。</p><form class="research-form"><input name="product" aria-label="研究品种" placeholder="例如：中证1000、沪铜、原油" required maxlength="60"><button class="primary" type="submit">开始深入研究 ↗</button></form><p class="research-status" role="status">DeepSeek V4.1 Flash 生成 · 报告通常需要几分钟；可以切换页面，后台继续研究。</p><details><summary>研究方法与数据范围</summary><p>旧判断审计 → 隔夜与全球环境 → 品种传导 → 量价仓验证 → 情景与反证 → 下次复盘。股指、国债、商品采用各自专题。参考已抽样阅读的 IMA 研究结构，未自动同步订阅正文；缺少的实时数据明确列为待补。</p><p>研究池：交易日累计成交量和当前持仓量都必须大于1万手。数据缺失也不进入研究池。</p></details><button class="quiet research-cancel" hidden>取消当前研究</button><h3>最近研究</h3><div class="research-history"></div><article class="research-output"></article>`;parent.prepend(host);
 host.querySelector('input[name=product]').value=product;
 const status=host.querySelector('.research-status'),out=host.querySelector('.research-output'),form=host.querySelector('form'),button=form.querySelector('button');let timer,retries=0,pollSequence=0;
 const show=job=>{const cancel=host.querySelector('.research-cancel');cancel.hidden=job.status!=='running';cancel.onclick=async()=>{cancel.disabled=true;try{const r=await fetch('/api/research/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:job.id})});if(!r.ok)throw Error('取消失败，请重试');poll(job.id)}catch(e){status.textContent=e.message}finally{cancel.disabled=false}};status.textContent=job.status==='failed'?job.error:job.name+' · '+job.stage;button.disabled=job.status==='running';if(job.report){out.replaceChildren();const title=document.createElement('h2');title.textContent=job.name+' · 深度研究报告';out.append(title);const stamp=document.createElement('p');stamp.textContent=(job.provider?job.provider+' · '+job.model+' · ':'历史报告 · ')+'生成 '+new Date(job.completed).toLocaleString()+' · 报价时间 '+(job.evidence?.quote?.quoteTime||'未知')+' · 交易日 '+(job.evidence?.quote?.tradingDay||'未知')+' · 采集时间 '+(job.dataAsOf||'未知');out.append(stamp);const audit=document.createElement('p');audit.textContent=(job.comparison?.notice||'历史报告暂无结构化对照')+' · '+(job.review?('已读取来源 '+job.review.readSources+' 份；结构缺项 '+job.review.missingSections.length+'；未匹配引用 '+job.review.unverifiedLinks.length+'。待人工核验。'):'');out.append(audit);if(job.sources?.length){const evidence=document.createElement('details');const summary=document.createElement('summary');summary.textContent='查看本次来源记录';evidence.append(summary);for(const item of job.sources){const row=document.createElement('p');row.textContent=item.name==='search_official_sources'?'检索：'+item.args.query+' · '+(item.result?.items?.length||0)+' 条官方结果':'读取：';if(item.result?.url){const a=document.createElement('a');a.textContent=item.result.url;a.href=item.result.url;a.target='_blank';a.rel='noopener noreferrer';row.append(a)}if(item.result?.error)row.append(document.createTextNode(item.result.error));evidence.append(row)}out.append(evidence)}if(job.comparison?.previousId){const prev=document.createElement('button');prev.className='quiet';prev.textContent='查看上一版研究';prev.onclick=()=>poll(job.comparison.previousId);out.append(prev)}const body=document.createElement('div');renderMarkdown(body,job.report);out.append(body);const download=document.createElement('button');download.className='quiet';download.textContent='下载 Markdown 报告';download.onclick=()=>{const u=URL.createObjectURL(new Blob([job.report],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=job.name+'-研究报告.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};out.prepend(download);const follow=document.createElement('section');follow.innerHTML='<h3>判断复核记录</h3><p>记录事实与依据；这些记录会进入下一次同品种研究，不会改写原报告。</p><div class="followup-list"></div><form><select aria-label="复核状态"><option value="pending">仍待验证</option><option value="supported">得到支持</option><option value="refuted">出现反证</option><option value="expired">已失效或过期</option></select><textarea aria-label="复核依据" placeholder="写明原判断、新证据、时间和来源" required maxlength="3000"></textarea><button type="submit" class="quiet">保存复核记录</button><p role="status"></p></form>';
 const list=follow.querySelector('.followup-list');const labels={pending:'仍待验证',supported:'得到支持',refuted:'出现反证',expired:'已失效或过期'};for(const entry of job.followups||[]){const p=document.createElement('p');p.textContent=new Date(entry.created).toLocaleString()+' · '+labels[entry.status]+' · '+entry.note;list.append(p)}
 const reviewForm=follow.querySelector('form');reviewForm.onsubmit=async e=>{e.preventDefault();const submit=reviewForm.querySelector('button'),message=reviewForm.querySelector('p');submit.disabled=true;try{const r=await fetch('/api/research/followup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:job.id,status:reviewForm.querySelector('select').value,note:reviewForm.querySelector('textarea').value})});const result=await r.json();if(!r.ok)throw Error(result.error||'保存失败');await poll(job.id)}catch(error){message.textContent=error.message}finally{submit.disabled=false}};out.append(follow)}};
 const history=async()=>{const r=await fetch('/api/research/reports');if(!r.ok)return;const list=await r.json();const box=host.querySelector('.research-history');box.replaceChildren();for(const j of list.slice(0,8)){const b=document.createElement('button');b.className='quiet';b.textContent=j.name+' · '+new Date(j.created).toLocaleDateString();b.onclick=()=>poll(j.id);box.append(b)}if(!list.length)box.textContent='首次研究完成后自动保存在本机。'};
 async function poll(id){const sequence=++pollSequence;clearTimeout(timer);try{const r=await fetch('/api/research/reports/'+encodeURIComponent(id),{signal:AbortSignal.timeout(10000)});const j=await r.json();if(!host.isConnected||sequence!==pollSequence)return;if(!r.ok){if(r.status===404){status.textContent='报告不存在，请重新选择';button.disabled=false;return}throw Error(j.error)}retries=0;show(j);if(j.status==='running')timer=setTimeout(()=>poll(id),2000);else{if(localStorage.getItem('jarvis-research-job')===id)localStorage.removeItem('jarvis-research-job');await history()}}catch(e){if(!host.isConnected||sequence!==pollSequence)return;retries++;status.textContent='连接暂时中断，正在恢复查询；不会重复启动研究。';timer=setTimeout(()=>poll(id),Math.min(30000,2000*2**Math.min(retries,4)))}}
 form.onsubmit=async e=>{e.preventDefault();button.disabled=true;out.replaceChildren();status.textContent='正在冻结行情并启动研究…';try{const r=await fetch('/api/research/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product:form.elements.product.value.trim()})});const j=await r.json();if(!r.ok)throw Error(j.error);localStorage.setItem('jarvis-research-job',j.id);poll(j.id)}catch(e){status.textContent=e.message;button.disabled=false}};
 try{const recent=await history();const pending=localStorage.getItem('jarvis-research-job')||recent?.find(j=>j.status==='running')?.id;if(pending)poll(pending)}catch{status.textContent='研究服务不可用，请检查本地服务。'}
}
